// TH15 synthetic training aliases, copied from transcribe/th15/touhou-bullets.ecl.
// Source etSprite types used by this card: 7 (RING_BALL2) and 8 (RICE).
const TH15_RING_BALL2: int = 464;
const TH15_RICE: int = 480;

// th15_s2_w09 — TH15 v1.00b Stage 2 mid-stage wave 09.
// Source entry st02.ecl.txt:1112-1141 (MainSub06); deps:
//   GirlA01 8-24, GirlA01_at 26-64, GirlBlueA01e 293-301,
//   GirlD02 606-629, GirlD02_at 631-686, GirlRedA01e 748-756.
// Card frame 0 = source MainSub06 entry; the source wave starts after the
// 120-frame independent shell buffer.
const TIME_LIMIT: int = 2124;   // 120 opening + 2000 schedule/tail estimate + 4 startup
const OPENING_BUFFER: int = 120;

// GirlD02_at (667): etEx type 8 ANGLE_ACCEL, a=30, r=0, s=RANDF2*0.05deg/frame.
// The source samples the expression when configuring the wave, so one value is
// shared by every bullet of that wave (quantized to BAM/frame here).
xformdef TURN30(w: angle) {
    @30 set_ang_vel(w);
    set_ang_vel(0deg);
}

// ---------------------------------------------------------------------------
// source GirlA01 (8-24), body shared by GirlRedA01e (748-756) and
// GirlBlueA01e (293-301); those wrappers also start GirlA01_at async.
// mirror != 0 is source enmCreateM: child mirror initial 1 negates x velocity,
// so the commanded angles become 180deg-angle. Spawn x itself is unchanged
// because MainSub06 is not mirrored.
// ---------------------------------------------------------------------------
async sub fairy(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24): modern round rule, first value * 0.5
    set_hitbox(8fx);     // setHitbox(16,16): first value * 0.5
    spawn fairy_shot();  // @GirlA01_at() async

    var a1: angle = 67.5deg;    // moveVel(1.1780972, 2.0)
    var a2: angle = 22.5deg;    // moveVelTime(60, 0, 0.3926991, 3.0)
    var a3: angle = 45deg;      // moveVelTime(60, 0, 0.7853982, 2.0)
    if mirror != 0 {
        a1 = 112.5deg;
        a2 = 157.5deg;
        a3 = 135deg;
    }
    move_vel(0, a1, 2fx, EASE_LINEAR);
    wait(30);
    move_vel(60, a2, 3fx, EASE_LINEAR);
    wait(60);
    move_vel(60, a3, 2fx, EASE_LINEAR);
    loop { wait(1000); }        // source GirlA01_256 idle loop
}

// source GirlA01_at (26-64): wait(40 + RAND%140), then one etOn.
// etAim mode 3 (fixed-direction ring): alpha=90deg, delta=0; N ways from the
// last pushed stack value (3/3/5/5), M layers from the first (1/2/4/6);
// layer speeds s0=1.5/1.5/2.5/3.5 down to s1=1.0 (step -0.5).
async sub fairy_shot() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 3;
    var layers: int = 1;
    var s0: fx = 1.5fx;
    var step: fx = 0fx;
    if rank == RANK_NORMAL {
        layers = 2;
        step = -0.5fx;
    } else if rank == RANK_HARD {
        ways = 5;
        layers = 4;
        s0 = 2.5fx;
        step = -0.5fx;
    } else if rank == RANK_LUNATIC {
        ways = 5;
        layers = 6;
        s0 = 3.5fx;
        step = -0.5fx;
    }
    wait(40 + rand(140));

    sh_reset(0);
    sh_sprite(0, TH15_RICE, 6);   // etSprite(0, 8, 6)
    sh_ring(0, 1);                // etAim mode 3 ring, delta 0
    sh_aim(0, 0);
    sh_count(0, ways, layers);
    sh_speed(0, s0, step);
    sh_angle(0, 90deg, 0deg);     // etAngle(0, pi/2, 0)
    sh_fire(0);
}

// ---------------------------------------------------------------------------
// source GirlD02 (606-629)
// ---------------------------------------------------------------------------
async sub girl_d02() {
    set_invuln(65535);
    set_hurtbox(16fx);   // setHurtbox(32,32): 32 * 0.5
    set_hitbox(12fx);    // setHitbox(24,24): 24 * 0.5
    move_vel(0, 90deg, 3fx, EASE_LINEAR);       // moveVel(pi/2, 3.0)
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);     // moveVelTime(80, 1, pi/2, 0)
    spawn girl_d02_shot();                      // @GirlD02_at() async
    wait(240);
    move_speed(120, 1fx, EASE_QUAD_IN);         // moveSpeedTime(120, 1, 1.0)
    wait(60);
    loop { wait(1000); }                        // GirlD02_440 idle loop
}

// source GirlD02_at (631-686)
async sub girl_d02_shot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var ways: int = 8;
    var shots: int = 10;
    var interval: int = 80;
    var speed: fx = 1.6fx;
    if rank == RANK_NORMAL {
        shots = 20;
        interval = 40;
    } else if rank == RANK_HARD {
        ways = 10;
        shots = 40;
        interval = 20;
        speed = 2.6fx;
    } else if rank == RANK_LUNATIC {
        ways = 13;
        shots = 80;
        interval = 15;
        speed = 3.6fx;
    }
    var n: int = 0;
    while n < shots {
        d02_wave(ways, speed);
        n = n + 1;
        wait(interval);
    }
}

// etAim mode 9 (aimed alternating-layer ring): A + alpha + (-1)^q*(R(i)+H(M,q)),
// alpha=0, delta=3deg, M=3 -> H = 0, delta, delta; all layers use the same speed.
sub d02_wave(ways: int, speed: fx) {
    var aim: int = aim_player() as int;
    var delta: int = 3deg as int;
    var w: angle = (rand(19) - 9) as angle;   // RANDF2*0.00087266 rad/frame in BAM, once per wave
    for q in 0..3 {
        var h: int = ((q + 1) / 2) * delta;
        for i in 0..ways {
            var a: int = (i * 65536) / ways + h;
            if q % 2 != 0 { a = 0 - a; }
            _ = fire(TH15_RING_BALL2, 2, $self_x, $self_y, speed,
                     (aim + a) as angle, TURN30(w), none);
        }
    }
}

// ---------------------------------------------------------------------------
// source MainSub06 (1112-1141): D02 pairs at frames 0/380, right-side then
// left-side fairy pairs every 20 frames (10 each). B/C are do-while counters.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-144fx, -24fx, 1000, 0, 1000, 0, girl_d02);
    _ = spawn_enemy(144fx, -24fx, 1000, 0, 1000, 0, girl_d02);
    wait(180);

    for b in 0..10 {              // enmCreateM at %A = 192, $B = 10
        _ = spawn_enemy(192fx, -16fx, 100, 0, 1000, 0, fairy(1));
        wait(10);
        _ = spawn_enemy(192fx, -28fx, 100, 0, 1000, 0, fairy(1));
        wait(10);
    }

    _ = spawn_enemy(-64fx, -24fx, 1000, 0, 1000, 0, girl_d02);
    _ = spawn_enemy(64fx, -24fx, 1000, 0, 1000, 0, girl_d02);

    for c in 0..10 {              // enmCreate at %A = -192, $C = 10
        _ = spawn_enemy(-192fx, -16fx, 100, 0, 1000, 0, fairy(0));
        wait(10);
        _ = spawn_enemy(-192fx, -28fx, 100, 0, 1000, 0, fairy(0));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
